@dataclass
class Token:
    type: str
    value: str
    line: int
    col: int

def lex(source: str) -> Generator[Token, None, None]:
    line, col = 1, 0
    i = 0
    while i < len(source):
        ch = source[i]
        if ch == '\n':
            line += 1; col = 0; i += 1; continue
        if ch.isspace():
            col += 1; i += 1; continue
        if ch.isdigit():
            start = i
            while i < len(source) and source[i].isdigit(): i += 1
            yield Token('NUMBER', source[start:i], line, col)
            continue
        if ch.isalpha():
            start = i
            while i < len(source) and source[i].isalnum(): i += 1
            yield Token('IDENT', source[start:i], line, col)
            continue
        yield Token('PUNCT', ch, line, col); i += 1; col += 1

