T = TypeVar('T')
E = TypeVar('E')

class Result(Generic[T, E]):
    def __init__(self, value: Optional[T] = None, error: Optional[E] = None):
        self._value = value
        self._error = error
        self._is_ok = error is None

    @classmethod
    def ok(cls, value: T) -> Result[T, E]:
        return cls(value=value)

    @classmethod
    def err(cls, error: E) -> Result[T, E]:
        return cls(error=error)

    def map(self, fn: Callable[[T], U]) -> Result[U, E]:
        if self._is_ok:
            try: return Result.ok(fn(self._value))
            except Exception as e: return Result.err(e)
        return self

    def flat_map(self, fn: Callable[[T], Result[U, E]]) -> Result[U, E]:
        return fn(self._value) if self._is_ok else self

    def get_or(self, default: T) -> T:
        return self._value if self._is_ok else default

    def __repr__(self):
        return f'Ok({self._value!r})' if self._is_ok else f'Err({self._error!r})'

