from typing import Any

class MetaModel(type):
    def __new__(mcs, name, bases, namespace):
        fields = {k: v for k, v in namespace.items() if isinstance(v, type)}
        for field_name in fields:
            namespace.pop(field_name, None)
        cls = super().__new__(mcs, name, bases, namespace)
        cls.__fields__ = fields
        cls.__validators__ = {}
        for k, v in namespace.items():
            if callable(v) and hasattr(v, '__validates__'):
                cls.__validators__[v.__validates__] = v
        return cls

    def __call__(cls, **kwargs):
        instance = cls.__new__(cls)
        errors = {}
        for field, ftype in cls.__fields__.items():
            val = kwargs.get(field)
            if not isinstance(val, ftype):
                errors[field] = f'Expected {ftype.__name__}, got {type(val).__name__}'
            else:
                validator = cls.__validators__.get(field)
                if validator:
                    try: validator(instance, val)
                    except ValueError as e: errors[field] = str(e)
                object.__setattr__(instance, field, val)
        if errors: raise TypeError(f'Validation failed: {errors}')
        return instance

