        self._entries = {}

    def push(self, item, priority=None):
        p = priority if priority is not None else self._key(item)
        if item in self._entries:
            self._mark_removed(item)
        entry = [p, self._counter, item]
        self._entries[item] = entry
        heapq.heappush(self._heap, entry)
        self._counter += 1

    def _mark_removed(self, item):
        entry = self._entries.pop(item)
        entry[-1] = self._REMOVED

    def pop(self):
        while self._heap:
            _, _, item = heapq.heappop(self._heap)
            if item is not self._REMOVED:
                del self._entries[item]
                return item
        raise KeyError('pop from empty queue')

    def __len__(self): return len(self._entries)
    def __contains__(self, item): return item in self._entries

from __future__ import annotations
from typing import TypeVar, Generic, Callable, Iterator, Iterable
from dataclasses import dataclass

T = TypeVar('T')
U = TypeVar('U')

@dataclass
class Stream(Generic[T]):
    _source: Iterator[T]

    @classmethod
    def of(cls, *items: T) -> Stream[T]:
        return cls(iter(items))

    @classmethod
    def from_iterable(cls, it: Iterable[T]) -> Stream[T]:
        return cls(iter(it))

    def map(self, fn: Callable[[T], U]) -> Stream[U]:
        return Stream(fn(x) for x in self._source)

    def filter(self, pred: Callable[[T], bool]) -> Stream[T]:
        return Stream(x for x in self._source if pred(x))

    def flat_map(self, fn: Callable[[T], Iterable[U]]) -> Stream[U]:
        return Stream(y for x in self._source for y in fn(x))

    def take(self, n: int) -> Stream[T]:
        def _take():
            for i, x in enumerate(self._source):
                if i >= n: break
                yield x
        return Stream(_take())

    def reduce(self, fn: Callable[[U, T], U], initial: U) -> U:
        acc = initial
        for x in self._source:
            acc = fn(acc, x)
        return acc

    def to_list(self) -> list[T]:
        return list(self._source)

result = (
    Stream.from_iterable(range(100))
    .filter(lambda x: x % 2 == 0)
    .map(lambda x: x ** 2)
    .take(5)
    .to_list()
)
print(result)

from __future__ import annotations
from typing import NamedTuple, Any
import hashlib, json

class Block(NamedTuple):
    index: int
    data: Any
    previous_hash: str
    nonce: int = 0

    def compute_hash(self) -> str:
        content = json.dumps([self.index, self.data, self.previous_hash, self.nonce], sort_keys=True)
        return hashlib.sha256(content.encode()).hexdigest()

    def mine(self, difficulty: int = 3) -> Block:
        target = '0' * difficulty
        nonce = 0
        while True:
            candidate = self._replace(nonce=nonce)
            if candidate.compute_hash().startswith(target):
                return candidate
            nonce += 1

class Blockchain:
    def __init__(self, difficulty: int = 3):
        self.difficulty = difficulty
        genesis = Block(0, 'Genesis', '0' * 64).mine(difficulty)
        self.chain = [genesis]

    def add(self, data: Any) -> Block:
        prev = self.chain[-1]
        block = Block(len(self.chain), data, prev.compute_hash()).mine(self.difficulty)
        self.chain.append(block)
        return block

    def is_valid(self) -> bool:
        for i in range(1, len(self.chain)):
            curr, prev = self.chain[i], self.chain[i - 1]
            if curr.previous_hash != prev.compute_hash():
                return False
        return True

bc = Blockchain(difficulty=2)
bc.add({'tx': 'Alice -> Bob', 'amount': 50})
bc.add({'tx': 'Bob -> Carol', 'amount': 20})
print(f'Valid: {bc.is_valid()}, Length: {len(bc.chain)}')
